"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["4409"],{73300(e){e.exports=JSON.parse('{"id":"FIN-1253","slug":"human-capital","term":"Human Capital","also_known_as":[],"difficulty":"Advanced","definition":"Human capital is the knowledge, skills, health, experience and abilities that people possess, which make them productive and allow them to earn income.","explanation":["Just as physical capital, such as machinery and buildings, helps produce goods and services, human capital makes workers more productive. It can be increased through education, training, work experience and good health.","The concept was developed by economists such as Gary Becker and Theodore Schultz in the mid-twentieth century. It explains why individuals and governments invest in education and why more skilled workers tend to earn higher wages.","For example, a person who spends several years training as an engineer increases their human capital, expecting higher lifetime earnings in return for the time and cost of study.","At the national level, human capital is a major driver of economic growth and innovation. Countries invest in schools, universities, healthcare and training programmes to strengthen it. In personal finance, human capital is often viewed as a person\'s most valuable asset early in life, which is one reason younger people can sometimes take more investment risk with their savings."],"note":"","total":1725,"prev":{"slug":"house-price-index","term":"House Price Index"},"next":{"slug":"human-development-index","term":"Human Development Index"}}')}}]);